/*
 * Noto Sans (SIL Open Font License 1.1), regular and bold, cut down to Latin, Latin
 * Extended, punctuation and the rupee sign with fonttools' pyftsubset, so school PDFs can
 * show names like "Zoë Müller" and "₹" while the server bundle stays small. Embedded as
 * base64 rather than read from disk so serverless hosts always have them.
 * To rebuild: pyftsubset NotoSans-Regular.ttf --unicodes="U+0020-007E,U+00A0-024F,
 * U+2010-2027,U+2030-203A,U+20B9,U+2122,U+2190-2193,U+2713" --layout-features="kern,liga"
 */

export const NOTO_SANS_REGULAR = ""

export const NOTO_SANS_BOLD = ""
